","expected_pattern":null,"case_type":"benign","notes":"แจ้งส่งของโดยไม่มีค่าธรรมเนียม"},{"case_id":"benign_team_update","input_text":"งานส่วนแรกเสร็จแล้ว เหลือทบทวนเอกสารก่อนส่งให้ทีม","expected_pattern":null,"case_type":"benign","notes":"อัปเดตงานทั่วไป"},{"case_id":"benign_friend_chat","input_text":"เสาร์นี้ว่างไหม อยากชวนไปกินข้าวและคุยเรื่องทริป","expected_pattern":null,"case_type":"benign","notes":"บทสนทนาเพื่อนทั่วไป"},{"case_id":"borderline_bank_warning","input_text":"ธนาคารไม่มีนโยบายขอรหัสโอทีพี กรุณาอย่าส่งรหัสให้ผู้อื่นและติดต่อช่องทางทางการ","expected_pattern":null,"case_type":"borderline_legitimate","notes":"คำเตือนที่มีคำ scam-like แต่ห้ามส่ง OTP"},{"case_id":"borderline_government_notice","input_text":"ได้รับหนังสือแจ้งจากหน่วยงาน กรุณาตรวจสอบเลขอ้างอิงผ่านเว็บไซต์ทางการโดยไม่ต้องโอนเงิน","expected_pattern":null,"case_type":"borderline_legitimate","notes":"ประกาศทางการพร้อมแนวทางตรวจสอบ"},{"case_id":"borderline_parcel_cod","input_text":"พัสดุเก็บเงินปลายทาง โปรดตรวจชื่อผู้ส่งและปฏิเสธรับได้หากไม่ได้สั่ง","expected_pattern":null,"case_type":"borderline_legitimate","notes":"พัสดุถูกต้องและให้สิทธิ์ปฏิเสธ"},{"case_id":"borderline_it_support","input_text":"ฝ่ายไอทีนัดช่วยติดตั้งโปรแกรมผ่านหน้าจอร่วมกันตามใบงานที่คุณเปิดไว้","expected_pattern":null,"case_type":"borderline_legitimate","notes":"remote support ที่ผู้ใช้เริ่มและมีใบงาน"},{"case_id":"borderline_investment_warning","input_text":"การลงทุนมีความเสี่ยงและไม่รับประกันผลตอบแทน โปรดอ่านข้อมูลก่อนตัดสินใจ","expected_pattern":null,"case_type":"borderline_legitimate","notes":"คำเตือนลงทุนที่ไม่รับประกัน"},{"case_id":"borderline_prize_terms","input_text":"กิจกรรมแจกของรางวัลมีเงื่อนไขชัดเจนและไม่มีการเรียกเก็บค่าธรรมเนียมจากผู้รับ","expected_pattern":null,"case_type":"borderline_legitimate","notes":"กิจกรรมจริงที่ย้ำว่าไม่มีค่าธรรมเนียม"},{"case_id":"sparse_urgent","input_text":"ด่วนมาก","expected_pattern":null,"case_type":"short_sparse","notes":"สั้นเกินกว่าจะระบุ pattern"},{"case_id":"sparse_call_back","input_text":"ช่วยโทรกลับด้วย","expected_pattern":null,"case_type":"short_sparse","notes":"คำขอทั่วไปที่ไม่มีบริบท"},{"case_id":"sparse_parcel","input_text":"มีพัสดุ","expected_pattern":null,"case_type":"short_sparse","notes":"กล่าวถึงพัสดุแต่ไม่มีคำขอจ่าย"},{"case_id":"sparse_received","input_text":"ได้รับเงินแล้ว","expected_pattern":null,"case_type":"short_sparse","notes":"ข้อความยืนยันสั้นทั่วไป"},{"case_id":"typo_bank","input_text":"แบงค์โทรมาบอกไห้ส่งโค้ดยืนยันด่วน ไม่งั้นบันชีโดนล้อก","expected_pattern":"BANK_OTP_IMPERSONATION","case_type":"typo_informal_thai","notes":"ภาษาไทยไม่เป็นทางการและสะกดผิด"},{"case_id":"typo_job","input_text":"งานกดไล้ เติมตังก่อนนะ เด่วทำครบละถอนได้หมด","expected_pattern":"FAKE_JOB_RECHARGE","case_type":"typo_informal_thai","notes":"ภาษาพูดและคำย่อ"},{"case_id":"mixed_remote","input_text":"Support แจ้งว่า device มีปัญหา ให้ install แอปแล้ว share screen ตอนนี้","expected_pattern":"REMOTE_SUPPORT","case_type":"mixed_thai_english","notes":"ข้อความไทยปนอังกฤษเกี่ยวกับ remote access"},{"case_id":"mixed_investment","input_text":"ลงทุน package นี้ guaranteed profit ไม่มี loss รีบ transfer ก่อนปิดรอบ","expected_pattern":"INVESTMENT_GUARANTEED_RETURN","case_type":"mixed_thai_english","notes":"ข้อความไทยปนอังกฤษเกี่ยวกับผลตอบแทน"}]};
// Trusted operator-only filter. Empty means all cases; for a smoke test use ['prize_fee_02'].
const CALIBRATION_CASE_IDS = [];
const requested = new Set(CALIBRATION_CASE_IDS);
const selectedCases = requested.size === 0
  ? DATASET.cases
  : DATASET.cases.filter((testCase) => requested.has(testCase.case_id));
if (requested.size > 0 && selectedCases.length !== requested.size) throw new Error('Unknown calibration case_id in operator filter.');
return selectedCases.map((testCase) => ({
  json: {
    case_id: testCase.case_id,
    input_text: testCase.input_text,
    expected_pattern: testCase.expected_pattern,
    case_type: testCase.case_type,
    notes: testCase.notes,
    context: {
      request_id: testCase.case_id,
      analysis_id: 'calibration-' + testCase.case_id,
      content: testCase.input_text,
      language: 'th'
    }
  }
}));

return $input.all().map((item) => {
  const calibration = item.json || {};
  if (
    typeof calibration.case_id !== 'string' || !calibration.case_id ||
    typeof calibration.input_text !== 'string' || !calibration.input_text.trim()
  ) throw new Error('Calibration case cannot be adapted to semantic lookup input.');
  return {
    json: {
      context: {
        request_id: calibration.case_id,
        analysis_id: 'calibration-' + calibration.case_id,
        content: calibration.input_text,
        language: 'th'
      }
    }
  };
});

const lookup = JSON.parse(JSON.stringify($input.first().json || {}));
const request = $('Loop Over Calibration Cases').item.json;
const caseId = request && request.context && request.context.request_id;
if (typeof caseId !== 'string' || !caseId) throw new Error('Calibration correlation key is missing.');
const returnedId = lookup.context && lookup.context.request_id
  ? lookup.context.request_id
  : lookup.public_response && lookup.public_response.request_id
    ? lookup.public_response.request_id
    : null;
if (returnedId !== null && returnedId !== caseId) throw new Error('Semantic lookup correlation key mismatch.');
return [{ json: { case_id: caseId, lookup_result: lookup } }];

const definitions = $('Load Calibration Cases').all().map((item) => item.json);
const definitionById = new Map(definitions.map((item) => [item.case_id, item]));
const results = $input.all().map((item) => item.json || {}).map((correlated) => {
  const caseId = correlated.case_id;
  const lookup = correlated.lookup_result || {};
  const definition = definitionById.get(caseId);
  if (!definition) throw new Error('Semantic calibration returned an unknown case.');
  if (lookup.ok !== true || !lookup.semantic_intelligence || !Array.isArray(lookup.semantic_intelligence.patterns)) {
    return {
      case_id: caseId,
      input_text: definition.input_text,
      expected_pattern: definition.expected_pattern,
      case_type: definition.case_type,
      notes: definition.notes,
      ok: false,
      patterns: [],
      status_code: Number.isInteger(Number(lookup.status_code)) ? Number(lookup.status_code) : null,
      semantic_error_code: lookup.public_response && lookup.public_response.error && typeof lookup.public_response.error.code === 'string'
        ? lookup.public_response.error.code
        : 'SEMANTIC_LOOKUP_FAILED',
      error_category: lookup.internal_diagnostics && lookup.internal_diagnostics.semantic_lookup
        ? lookup.internal_diagnostics.semantic_lookup.error_category || 'lookup_failed'
        : 'lookup_failed'
    };
  }
  return {
    case_id: caseId,
    input_text: definition.input_text,
    expected_pattern: definition.expected_pattern,
    case_type: definition.case_type,
    notes: definition.notes,
    ok: true,
    patterns: lookup.semantic_intelligence.patterns.map((pattern) => ({
      pattern_code: pattern.pattern_code,
      category: pattern.category,
      best_similarity: pattern.best_similarity,
      average_similarity: pattern.average_similarity,
      matched_example_count: pattern.matched_example_count
    }))
  };
}).sort((a, b) => a.case_id < b.case_id ? -1 : a.case_id > b.case_id ? 1 : 0);
if (results.length !== definitions.length) throw new Error('Semantic calibration result count mismatch.');
return [{ json: { dataset_version: '1.0.0', results } }];
